/**
 * BrokerStatusResponse
 *
 * Response schema describing the current broker connection status.
 *
 * Attributes:
 * connected: ``True`` if an active connection exists for the
 * authenticated user and the requested broker.
 * last_sync_at: UTC timestamp of the most recent successful trade sync,
 * or ``None`` if no sync has been performed.
 */
export type BrokerStatusResponse = {
    /**
     * Connected
     *
     * True if an active connection exists for this broker. False if the user has not connected or has disconnected.
     */
    connected: boolean;
    /**
     * Last Sync At
     *
     * UTC timestamp of the most recent successful trade sync. Null if no sync has been performed since connecting.
     */
    last_sync_at: string | null;
    /**
     * Schwab Oauth Mode
     *
     * The configured Schwab OAuth mode ('paste' or 'callback').
     */
    schwab_oauth_mode?: string | null;
};

/**
 * BrokerSyncResult
 *
 * Response schema summarising the result of a broker account sync.
 *
 * Attributes:
 * imported_count: Number of new trades successfully imported from
 * the broker API during this sync operation.
 * skipped_count: Number of orders that were skipped — either because
 * they already exist (deduplicated by ``broker_order_id``) or
 * because they could not be normalised.
 * errors: List of human-readable error messages for orders that failed
 * processing.  Empty when no errors occurred.
 */
export type BrokerSyncResult = {
    /**
     * Imported Count
     *
     * Number of new trades imported during this sync.
     */
    imported_count: number;
    /**
     * Skipped Count
     *
     * Number of orders skipped (already imported or could not be normalised).
     */
    skipped_count: number;
    /**
     * Errors
     *
     * Error messages for any orders that could not be processed.
     */
    errors?: Array<string>;
    /**
     * Warnings
     *
     * Informational or warning messages.
     */
    warnings?: Array<string>;
    /**
     * Trades Protected Reconciled
     *
     * Number of metadata-protected trades that absorbed new executions.
     */
    trades_protected_reconciled?: number;
    /**
     * Trades Protected Skipped
     *
     * Number of metadata-protected positions skipped.
     */
    trades_protected_skipped?: number;
    /**
     * Activity Log
     *
     * Informational log of routine, successful row-level outcomes ('created:'/'updated:'/'skipped:' lines). Not an error or warning signal.
     */
    activity_log?: Array<string>;
};

