/**
 * CorporateActionCreateRequest
 *
 * Public API request body for creating a new corporate action.
 *
 * The ``user_id`` field is NOT included here — it is injected by the route
 * handler from the authenticated JWT claim.
 *
 * Attributes:
 * symbol: Ticker symbol the action applies to.
 * date: Calendar date on which the split took effect.
 * ratio: Split ratio (after / before).
 * old_conid: Optional broker contract ID before the split.
 * new_conid: Optional broker contract ID after the split.
 */
export type CorporateActionCreateRequest = {
    /**
     * Symbol
     *
     * Ticker symbol the corporate action applies to (e.g. 'OTLK').
     */
    symbol: string;
    /**
     * Date
     *
     * Calendar date on which the split took effect (ISO 8601 date).
     */
    date: string;
    /**
     * Ratio
     *
     * Split ratio expressed as a Decimal. Greater than 1 for a forward split (e.g. 2.0 = 2:1 split). Less than 1 for a reverse split (e.g. 0.05 = 1:20 reverse split). Compute as after_shares / before_shares.
     */
    ratio: number | string;
    /**
     * Old Conid
     *
     * Broker contract ID before the split (IBKR conid). Required when the broker assigns a new instrument ID after the split.
     */
    old_conid?: string | null;
    /**
     * New Conid
     *
     * Broker contract ID after the split (IBKR conid). Required when the broker assigns a new instrument ID after the split.
     */
    new_conid?: string | null;
};

/**
 * CorporateActionRead
 *
 * Response schema returned for a single corporate action.
 *
 * Attributes:
 * id: UUID primary key.
 * user_id: UUID of the owning user.
 * symbol: Ticker symbol.
 * date: Effective date of the corporate action.
 * ratio: Split ratio.
 * old_conid: Broker contract ID before the split.
 * new_conid: Broker contract ID after the split.
 * created_at: Row creation timestamp.
 * updated_at: Row last-updated timestamp.
 */
export type CorporateActionRead = {
    /**
     * Id
     *
     * Unique identifier (UUID v4) assigned to this record by the database.
     */
    id: string;
    /**
     * User Id
     *
     * UUID of the user who owns this corporate action.
     */
    user_id: string;
    /**
     * Symbol
     *
     * Ticker symbol the corporate action applies to.
     */
    symbol: string;
    /**
     * Date
     *
     * Calendar date on which the split took effect.
     */
    date: string;
    /**
     * Ratio
     *
     * Split ratio expressed as a Decimal. Greater than 1 for a forward split (e.g. 2.0 = 2:1 split). Less than 1 for a reverse split (e.g. 0.05 = 1:20 reverse split). Compute as after_shares / before_shares.
     */
    ratio: string;
    /**
     * Old Conid
     *
     * Broker contract ID before the split. Null if not applicable.
     */
    old_conid: string | null;
    /**
     * New Conid
     *
     * Broker contract ID after the split. Null if not applicable.
     */
    new_conid: string | null;
    /**
     * Created At
     *
     * UTC timestamp of when this record was inserted into the database.
     */
    created_at: string;
    /**
     * Updated At
     *
     * UTC timestamp of the most recent update to this record.
     */
    updated_at: string;
};

/**
 * CorporateActionUpdate
 *
 * Request schema for partially updating an existing corporate action.
 *
 * All fields are optional.  Only supplied fields are updated in the DB.
 *
 * Attributes:
 * symbol: Updated ticker symbol.
 * date: Updated effective date.
 * ratio: Updated split ratio.
 * old_conid: Updated pre-split broker conid.  Set to null to clear.
 * new_conid: Updated post-split broker conid.  Set to null to clear.
 */
export type CorporateActionUpdate = {
    /**
     * Symbol
     *
     * Updated ticker symbol. Omit to leave unchanged.
     */
    symbol?: string | null;
    /**
     * Date
     *
     * Updated effective date. Omit to leave unchanged.
     */
    date?: string | null;
    /**
     * Ratio
     *
     * Updated split ratio. Split ratio expressed as a Decimal. Greater than 1 for a forward split (e.g. 2.0 = 2:1 split). Less than 1 for a reverse split (e.g. 0.05 = 1:20 reverse split). Compute as after_shares / before_shares.  Omit to leave unchanged.
     */
    ratio?: number | string | null;
    /**
     * Old Conid
     *
     * Updated pre-split broker conid. Omit to leave unchanged.
     */
    old_conid?: string | null;
    /**
     * New Conid
     *
     * Updated post-split broker conid. Omit to leave unchanged.
     */
    new_conid?: string | null;
};

