/**
 * DailyPnl
 *
 * Aggregated PnL for a single trading day.
 *
 * Attributes:
 * date: The calendar date of the trading day (UTC).
 * pnl: Total PnL realised across all closed trades on this day.
 * trade_count: Number of closed trades that day.
 * cumulative_pnl: Running cumulative PnL up to and including this day,
 * ordered chronologically from the earliest available trade.
 */
export type DailyPnl = {
    /**
     * Date
     *
     * Calendar date of the trading day (UTC).
     */
    date: string;
    /**
     * Pnl
     *
     * Total realised PnL for this day, summed across all closed trades whose ``closed_at`` date matches this day.
     */
    pnl: string;
    /**
     * Trade Count
     *
     * Number of closed trades with a PnL value that closed on this day.
     */
    trade_count: number;
    /**
     * Cumulative Pnl
     *
     * Running cumulative PnL up to and including this trading day, computed from the earliest available closed trade in the result set.
     */
    cumulative_pnl: string;
};

/**
 * DashboardFilterConfig
 *
 * Validated analytics filter configuration stored in saved views.
 */
export type DashboardFilterConfig = {
    /**
     * Date From
     *
     * Optional inclusive start date for closed trade filtering.
     */
    date_from?: string | null;
    /**
     * Date To
     *
     * Optional inclusive end date for closed trade filtering.
     */
    date_to?: string | null;
    /**
     * Playbook Ids
     *
     * Optional list of playbook IDs used to filter trades.
     */
    playbook_ids?: Array<string> | null;
    /**
     * Taxonomy Ids
     *
     * Optional list of taxonomy IDs used to filter trades.
     */
    taxonomy_ids?: Array<string> | null;
    /**
     * Status
     *
     * Optional status filter. If 'open', only open trades are included. If 'closed', only closed trades are included. If None, both are included.
     */
    status?: 'open' | 'closed' | null;
    /**
     * Optional trade direction filter.
     */
    direction?: Direction | null;
    /**
     * Account Ids
     *
     * Optional list of account IDs used to filter trades.
     */
    account_ids?: Array<string> | null;
    /**
     * Symbols
     *
     * Optional list of symbols to include.
     */
    symbols?: Array<string> | null;
    /**
     * Excluded Symbols
     *
     * Optional list of symbols to exclude.
     */
    excluded_symbols?: Array<string> | null;
    /**
     * Asset Classes
     *
     * Optional list of asset classes to include.
     */
    asset_classes?: Array<AssetClass> | null;
    /**
     * Currency Mode
     *
     * Currency handling mode for monetary analytics fields.
     */
    currency_mode?: 'NATIVE' | 'NORMALIZED';
    /**
     * Normalize To
     *
     * ISO-4217 target currency used when currency_mode is NORMALIZED.
     */
    normalize_to?: string | null;
    /**
     * Schema Version
     *
     * Filter schema version for future compatibility handling.
     */
    _schema_version?: string;
};

/**
 * Direction
 *
 * Trade direction — long (buy) or short (sell).
 */
export type Direction = 'LONG' | 'SHORT';

/**
 * FilterScope
 *
 * Scope of the saved filter — system (global) or user-owned.
 */
export type FilterScope = 'SYSTEM' | 'USER';

/**
 * FlexImportRequest
 *
 * Request body for the IBKR Flex Query automatic import endpoint.
 *
 * Attributes:
 * query_id: IBKR Flex Query ID configured in Account Management.
 * account_id: Optional UUID of the broker account to associate
 * imported trades with.
 * from_date: Optional start date (``YYYYMMDD``) to restrict the
 * report period sent to the Flex API.
 */
export type FlexImportRequest = {
    /**
     * Query Id
     *
     * IBKR Flex Query ID as configured in the IBKR Account Management portal under Reports → Flex Queries.
     */
    query_id: string;
    /**
     * Account Id
     *
     * UUID of the broker account to associate imported trades with; generic accounts are rejected because they support file imports only. The account_id query parameter takes precedence. Omit both to create trades without an account association.
     */
    account_id?: string | null;
    /**
     * From Date
     *
     * Optional start date in ``YYYYMMDD`` format. When supplied, only trades on or after this date are included in the Flex Query report.
     */
    from_date?: string | null;
    /**
     * Overwrite Manually Edited
     *
     * When true, trades that have been manually edited are no longer protected and will be overwritten by the incoming import data.
     */
    overwrite_manually_edited?: boolean;
};

