/**
 * GenericImportRowError
 *
 * One safe generic validation error, or the final truncation marker.
 */
export type GenericImportRowError = {
    /**
     * Location
     *
     * Physical CSV line number including the header, a zero-based JSON array location, or 'document' for document-level errors and the truncation marker.
     */
    location: number | string;
    /**
     * Field
     *
     * Invalid field name, or a document-level field such as header, encoding or record. The truncation marker uses 'errors'.
     */
    field: string;
    /**
     * Message
     *
     * Validation rule explanation naming the field without echoing supplied values, or a count of omitted errors.
     */
    message: string;
};

/**
 * GenericImportValidationDetail
 *
 * Structured HTTP 400 detail for file validation or persisted order-marker conflicts.
 */
export type GenericImportValidationDetail = {
    /**
     * Message
     *
     * Safe summary of the generic validation failure.
     */
    message: string;
    /**
     * Errors
     *
     * At most 200 row errors. If more errors exist, a final location='document', field='errors' marker states how many were omitted, making at most 201 entries including the marker.
     */
    errors: Array<GenericImportRowError>;
};

/**
 * HTTPValidationError
 */
export type HttpValidationError = {
    /**
     * Detail
     */
    detail?: Array<ValidationError>;
};

/**
 * ImportBadRequestResponse
 *
 * Documentation-only schema for existing import HTTP 400 response bodies.
 */
export type ImportBadRequestResponse = {
    /**
     * Detail
     *
     * Legacy string detail for parse/processing errors or an unacknowledged fresh-start; generic validation and persisted order-marker conflicts instead return a message and bounded safe field errors. No response envelope is used.
     */
    detail: string | GenericImportValidationDetail;
};

/**
 * ImportResult
 *
 * Result of a broker trade import operation.
 *
 * Attributes:
 * broker: Broker identifier used for this import (e.g. ``"ibkr"``).
 * filename: Source label supplied by the caller.
 * trades_parsed: Total number of trade rows successfully parsed from
 * the file.
 * trades_created: Number of trades actually persisted to the database.
 * trades_skipped: Number of rows that were skipped due to parse
 * errors or other non-fatal issues.
 * raw_transactions_created: Number of broker raw transactions newly
 * inserted during this import.
 * raw_suppressed_skipped: Number of BrokerRawTransaction records
 * skipped because their ``suppressed`` flag is ``True``.
 * raw_deleted_skipped: Number of BrokerRawTransaction records skipped
 * because their linked execution has ``deleted=True`` (user intent
 * preserved — execution was previously deleted by the user).
 * trades_protected_reconciled: Number of metadata-protected trades
 * encountered during rebuild and skipped from structural updates.
 * trades_protected_skipped: Number of metadata-protected positions
 * skipped because no existing trade could be resolved for them.
 * protected_positions_closed: Number of executions linked to open
 * metadata-protected trades via seed-lot matching.
 * unlinked_executions: Number of executions left unlinked because their
 * target contract belongs to a protected trade.
 * warnings: Human-readable descriptions of each skipped row.
 * activity_log: Informational log of routine created/updated rows.
 */
export type ImportResult = {
    /**
     * Broker
     *
     * Broker/parser identifier used for this import: 'ibkr', 'schwab' or 'generic'.
     */
    broker: string;
    /**
     * Filename
     *
     * Source label supplied by the caller. For uploaded files this is the original filename; for API-driven imports it may be a synthetic label such as `flex_query_{query_id}.xml` or `schwab_transactions_sync.json`.
     */
    filename: string;
    /**
     * Trades Parsed
     *
     * Total number of trade rows successfully parsed from the file. This is the sum of trades_created and trades_skipped.
     */
    trades_parsed: number;
    /**
     * Trades Created
     *
     * Number of trades that were persisted to the database.
     */
    trades_created: number;
    /**
     * Trades Skipped
     *
     * Number of rows that were skipped due to non-fatal parse errors. Inspect the warnings list for details.
     */
    trades_skipped: number;
    /**
     * Raw Transactions Created
     *
     * Number of broker raw transactions newly inserted during this import. Re-importing identical files should produce 0.
     */
    raw_transactions_created?: number;
    /**
     * Raw Suppressed Skipped
     *
     * Number of raw broker transactions skipped because their suppressed flag is true. Ordinary re-imports honor suppression; destructive history resets delete the raw records and their suppression flags.
     */
    raw_suppressed_skipped?: number;
    /**
     * Raw Deleted Skipped
     *
     * Number of raw broker transactions skipped because their linked execution was previously deleted by the user (``deleted=True``). Ordinary re-import does not recreate them; a destructive reset clears this history.
     */
    raw_deleted_skipped?: number;
    /**
     * Trades Protected Reconciled
     *
     * Number of metadata-protected trades (``is_manually_edited=True``) encountered during rebuild and skipped from structural updates.
     */
    trades_protected_reconciled?: number;
    /**
     * Trades Protected Skipped
     *
     * Number of metadata-protected positions skipped during this import because no existing trade could be resolved to reconcile them onto. See ``warnings`` for the affected symbol/date.
     */
    trades_protected_skipped?: number;
    /**
     * Protected Positions Closed
     *
     * Number of executions linked to open metadata-protected trades via seed-lot matching during projection rebuild.
     */
    protected_positions_closed?: number;
    /**
     * Unlinked Executions
     *
     * Number of executions left unlinked because their target contract belongs to a protected trade isolated from rebuild.
     */
    unlinked_executions?: number;
    /**
     * Warnings
     *
     * Non-fatal import warnings, including skipped rows and ignored generic CSV columns. Invalid generic rows reject the whole file with HTTP 400 rather than appearing as skipped-row warnings.
     */
    warnings?: Array<string>;
    /**
     * Activity Log
     *
     * Informational log of routine, successful row-level outcomes ('created:'/'updated:' lines). Not an error or warning signal — kept separate from `warnings` so callers never mistake normal import activity for a problem.
     */
    activity_log?: Array<string>;
};

/**
 * LinkBrokerTransactionRequest
 *
 * Request payload for linking a manual execution to a broker raw transaction.
 *
 * The execution must have ``origin='manual'``. On success the service sets
 * ``LogicalExecution.source_id`` to the given raw transaction ID and marks the
 * raw transaction ``suppressed=True`` so future imports skip it.
 */
export type LinkBrokerTransactionRequest = {
    /**
     * Raw Transaction Id
     *
     * Primary key of the BrokerRawTransaction to link (e.g. 'user:ibkr:3820422546').
     */
    raw_transaction_id: string;
};

/**
 * LinkBrokerTransactionResponse
 *
 * Response payload returned after linking a manual execution to a BRT.
 */
export type LinkBrokerTransactionResponse = {
    execution: LogicalExecutionRead;
    /**
     * Message
     */
    message: string;
};

/**
 * LogicalExecutionCreate
 *
 * Schema for creating a manual LogicalExecution.
 *
 * Note: ``origin`` is always set to ``'manual'`` by the service layer —
 * it is not accepted from the API consumer.
 */
export type LogicalExecutionCreate = {
    direction: Direction;
    /**
     * Quantity
     *
     * Execution quantity (absolute, always positive)
     */
    quantity: number | string;
    /**
     * Price
     *
     * Execution price per unit
     */
    price: number | string;
    /**
     * Commission
     *
     * Commission for this execution leg
     */
    commission?: number | string;
    /**
     * Executed At
     *
     * Timestamp of the execution (UTC)
     */
    executed_at: string;
    /**
     * Pnl
     *
     * Broker-reported realised P&L (None for opening legs)
     */
    pnl?: number | string | null;
    /**
     * Optional per-leg asset class override for COMBO trades. Ignored for non-COMBO parent trades.
     */
    asset_class?: AssetClass | null;
    /**
     * Multiplier
     *
     * Optional per-leg multiplier override for COMBO trades. Ignored for non-COMBO parent trades.
     */
    multiplier?: number | null;
};

/**
 * LogicalExecutionRead
 *
 * Schema for reading a LogicalExecution.
 */
export type LogicalExecutionRead = {
    direction: Direction;
    /**
     * Quantity
     *
     * Split-adjusted execution quantity for chart alignment
     */
    quantity: string;
    /**
     * Price
     *
     * Split-adjusted execution price per unit for chart alignment
     */
    price: string;
    /**
     * Commission
     *
     * Commission for this execution leg
     */
    commission?: string;
    /**
     * Executed At
     *
     * Timestamp of the execution (UTC)
     */
    executed_at: string;
    /**
     * Pnl
     *
     * Broker-reported realised P&L (None for opening legs)
     */
    pnl?: string | null;
    /**
     * Raw Price
     *
     * Original stored execution price per unit before split adjustment
     */
    raw_price?: string | null;
    /**
     * Raw Quantity
     *
     * Original stored execution quantity before split adjustment
     */
    raw_quantity?: string | null;
    /**
     * Id
     */
    id: string;
    /**
     * User Id
     */
    user_id: string;
    /**
     * Account Id
     */
    account_id?: string | null;
    /**
     * Symbol
     */
    symbol: string;
    /**
     * Conid
     */
    conid?: string | null;
    asset_class: AssetClass;
    /**
     * Pnl Eur
     */
    pnl_eur?: string | null;
    /**
     * Multiplier
     */
    multiplier: number;
    /**
     * Currency
     */
    currency?: string | null;
    /**
     * Open Close
     *
     * Opening/closing indicator: 'O' (opening), 'C' (closing), or null (mixed/unknown/manual)
     */
    open_close?: string | null;
    /**
     * Strike
     *
     * Option strike price derived from OCC symbol.
     */
    strike?: string | null;
    /**
     * Expiry
     *
     * Option expiry date derived from OCC symbol.
     */
    expiry?: string | null;
    /**
     * Option Type
     *
     * Option type derived from OCC symbol: 'C' or 'P'.
     */
    option_type?: string | null;
    /**
     * Origin
     *
     * Immutable provenance: imported | manual | merged | split
     */
    origin: 'imported' | 'manual' | 'merged' | 'split';
    /**
     * Deleted
     *
     * True when this execution has been soft-deleted
     */
    deleted: boolean;
    /**
     * User Modified
     *
     * True when the user has patched an imported, split, or merged execution
     */
    user_modified: boolean;
    /**
     * Source Id
     *
     * Broker raw transaction ID this execution was materialised from, or NULL. Set for imported executions and for manual executions linked via the link-broker-transaction endpoint. Clients use this to distinguish unlinked manual legs (potential duplicates) from linked replacements.
     */
    source_id?: string | null;
    /**
     * Parent Id
     *
     * FK to original execution for split/merge lineage
     */
    parent_id?: string | null;
    /**
     * Trade Id
     */
    trade_id?: string | null;
    /**
     * Created At
     */
    created_at: string;
    /**
     * Updated At
     */
    updated_at: string;
};

