/**
 * MergeExecutionsRequest
 *
 * Request payload for merging two or more executions into one.
 *
 * All source executions must belong to the same trade, have the same
 * direction and symbol, and must not already be deleted.
 *
 * The primary execution (``primary_id``) sets the ``parent_id`` for the
 * merged result.
 *
 * Attributes:
 * execution_ids: IDs of all executions to merge (must include at
 * least 2 entries; ``primary_id`` must be one of them).
 * primary_id: The execution whose metadata (price, executed_at) will
 * be used as the base for the merged result.
 * price: Override price for the merged execution.  Defaults to the
 * weighted-average price of the source executions.
 * executed_at: Override timestamp for the merged execution.  Defaults
 * to the timestamp of the primary execution.
 */
export type MergeExecutionsRequest = {
    /**
     * Execution Ids
     *
     * IDs of all executions to merge (at least 2 required).
     */
    execution_ids: Array<string>;
    /**
     * Primary Id
     *
     * The execution whose metadata is used as the base. Must be included in execution_ids.
     */
    primary_id: string;
    /**
     * Price
     *
     * Override price for the merged execution. When omitted, the weighted-average price is used.
     */
    price?: number | string | null;
    /**
     * Executed At
     *
     * Override timestamp for the merged execution (UTC). When omitted, the primary execution's timestamp is used.
     */
    executed_at?: string | null;
};

/**
 * MergeExecutionsResponse
 *
 * Response payload returned after merging executions.
 *
 * Attributes:
 * merged: The newly created merged execution.
 * sources: The original executions (now soft-deleted).
 */
export type MergeExecutionsResponse = {
    merged: LogicalExecutionRead;
    /**
     * Sources
     */
    sources: Array<LogicalExecutionRead>;
};

/**
 * MergeTradesRequest
 *
 * Payload for merging multiple trades into a single trade.
 *
 * Attributes:
 * trade_ids: List of UUIDs of the trades to merge. Must contain 2 to 10 UUIDs.
 */
export type MergeTradesRequest = {
    /**
     * Trade Ids
     *
     * UUIDs of trades to merge (2-10)
     */
    trade_ids: Array<string>;
};

