/**
 * TradePartialCloseRequest
 *
 * Payload for splitting an open trade by closing a portion of it.
 *
 * This request is used to 'trim' a position (e.g., selling 5 out of 20 shares).
 * The original trade's quantity is reduced, and a new closed trade is
 * created with the specified exit details and a deep copy of all metadata.
 *
 * Attributes:
 * quantity: Amount to close (must be > 0 and <= original trade quantity).
 * exit_price: Execution price for this partial close.
 * closed_at: Timezone-aware UTC timestamp of the close.
 * exit_commission: Additional commission paid for this exit.
 */
export type TradePartialCloseRequest = {
    /**
     * Quantity
     */
    quantity: number | string;
    /**
     * Exit Price
     */
    exit_price: number | string;
    /**
     * Closed At
     */
    closed_at: string;
    /**
     * Exit Commission
     */
    exit_commission?: number | string;
};

/**
 * TradeRead
 *
 * Response schema returned for a single trade.
 *
 * Attributes:
 * id: UUID primary key.
 * symbol: Ticker symbol.
 * direction: Long or short.
 * asset_class: Asset class.
 * quantity: Position size.
 * entry_price: Open execution price.
 * exit_price: Close execution price (``None`` if still open).
 * stop_loss: Stop-loss price (``None`` if not set).
 * take_profit: Take-profit price (``None`` if not set).
 * opened_at: Timestamp of position open.
 * closed_at: Timestamp of position close (``None`` if still open).
 * pnl: Realised PnL (``None`` if not yet closed / calculated).
 * commission: Commission paid.
 * journal: Free-text journal.
 * playbook_id: Optional UUID of the associated playbook.
 * trade_notes: List of psychological / review notes on this trade.
 * created_at: Row-creation timestamp.
 * updated_at: Row-last-updated timestamp.
 */
export type TradeRead = {
    /**
     * Id
     *
     * Unique identifier (UUID v4) assigned to this trade by the database.
     */
    id: string;
    /**
     * Position Id
     *
     * Stable business-position identifier shared by related trades.
     */
    position_id?: string | null;
    /**
     * Symbol
     *
     * Ticker symbol of the traded instrument.
     */
    symbol: string;
    /**
     * Trade direction: 'LONG' for a buy position, 'SHORT' for a sell position.
     */
    direction: Direction;
    /**
     * Asset class of the traded instrument.
     */
    asset_class: AssetClass | null;
    /**
     * Is Combo
     *
     * True when this trade is a multi-instrument COMBO position.
     */
    is_combo?: boolean;
    /**
     * Quantity
     *
     * Number of units, shares, or contracts traded.
     */
    quantity: string | null;
    /**
     * Entry Price
     *
     * Execution price at which the position was opened.
     */
    entry_price: string | null;
    /**
     * Exit Price
     *
     * Execution price at which the position was closed. Null if the trade is still open.
     */
    exit_price: string | null;
    /**
     * Chart Quantity
     *
     * Chart-adjusted quantity derived on read.
     */
    chart_quantity?: string | null;
    /**
     * Chart Entry Price
     *
     * Chart-adjusted entry price derived on read.
     */
    chart_entry_price?: string | null;
    /**
     * Chart Exit Price
     *
     * Chart-adjusted exit price derived on read.
     */
    chart_exit_price?: string | null;
    /**
     * Stop Loss
     *
     * Stop-loss price level. Null if no stop-loss was set.
     */
    stop_loss: string | null;
    /**
     * Take Profit
     *
     * Take-profit price level. Null if no take-profit was set.
     */
    take_profit: string | null;
    /**
     * Opened At
     *
     * Timezone-aware UTC timestamp of when the position was opened.
     */
    opened_at: string;
    /**
     * Closed At
     *
     * Timezone-aware UTC timestamp of when the position was closed. Null if the trade is still open.
     */
    closed_at: string | null;
    /**
     * Pnl
     *
     * Realised profit or loss in account currency. Null if the trade is still open or PnL has not been calculated.
     */
    pnl: string | null;
    /**
     * Net Pnl
     *
     * Realised net profit or loss in account currency. Null if the trade is still open or PnL has not been calculated.
     */
    net_pnl?: string | null;
    /**
     * Commission
     *
     * Total commission paid for this trade.
     */
    commission: string;
    /**
     * Journal
     *
     * Free-text journal attached to this trade. Null if no journal entry was added.
     */
    journal: string | null;
    /**
     * User Rating
     *
     * Optional user rating for this trade on a 1-5 scale.
     */
    user_rating?: number | null;
    /**
     * Tradingview Link
     *
     * Optional link to a TradingView chart.
     */
    tradingview_link?: string | null;
    /**
     * Image Urls
     *
     * Short-lived presigned GET URLs for trade images (expires in 1 hour).
     */
    image_urls?: Array<string>;
    /**
     * Currency
     *
     * ISO-4217 currency code of the trade (e.g. 'USD'). Null for legacy trades imported before EUR-reporting was added.
     */
    currency?: string | null;
    /**
     * Pnl Eur
     *
     * Realised P&L converted to EUR at the official Bundesbank daily rate on the trade date. Null for open trades or when the rate is unavailable.
     */
    pnl_eur?: string | null;
    /**
     * Net Pnl Eur
     *
     * Realised net P&L converted to EUR at the official Bundesbank daily rate on the trade date. Null for open trades or when the rate is unavailable.
     */
    net_pnl_eur?: string | null;
    /**
     * Playbook Id
     *
     * UUID of the playbook associated with this trade. Null if no playbook is assigned.
     */
    playbook_id?: string | null;
    /**
     * Playbook Name
     *
     * Name of the playbook associated with this trade, resolved from the joined playbook relationship. Null if no playbook is assigned.
     */
    playbook_name?: string | null;
    /**
     * Account Id
     *
     * UUID of the broker account this trade belongs to. Null if no account is assigned.
     */
    account_id?: string | null;
    /**
     * Portfolio Id
     *
     * UUID of the portfolio this trade belongs to via its account. Null if no account is assigned.
     */
    portfolio_id?: string | null;
    /**
     * Account Name
     *
     * Human-readable name of the broker account, resolved from the joined account relationship. Null if no account is assigned.
     */
    account_name?: string | null;
    /**
     * Account Type
     *
     * Type of the broker account (e.g. 'ibkr', 'schwab', 'manual'), resolved from the joined account relationship.
     */
    account_type?: string | null;
    /**
     * Taxonomies
     *
     * Taxonomy definitions assigned to this trade.
     */
    taxonomies?: Array<TaxonomyResponse>;
    /**
     * Annotations
     *
     * Resolved annotation values assigned to this trade.
     */
    annotations?: Array<TradeAnnotationResponse>;
    /**
     * Trade Notes
     *
     * Psychological and review notes attached to this trade.
     */
    trade_notes?: Array<TradeNoteRead>;
    /**
     * Legs
     *
     * Execution legs (entry and exit) for this trade.
     */
    legs?: Array<LogicalExecutionRead>;
    /**
     * Is Manually Edited
     *
     * When True, this trade was manually corrected and will be skipped on subsequent broker re-imports.
     */
    is_manually_edited?: boolean;
    /**
     * Has Conflict
     *
     * Aggregated/derived flag — True when the FIFO aggregator detected an unlinked duplicate pair (an imported leg and an unlinked manual leg sharing symbol, executed_at, direction, quantity, and price). Surfacing signal only; recomputed on every trade rebuild.
     */
    has_conflict?: boolean;
    /**
     * Has Unlinked Executions
     *
     * True when at least one broker execution was left unlinked because this protected trade could not absorb it during import.
     */
    has_unlinked_executions?: boolean;
    /**
     * Corporate Action Impact
     *
     * Corporate actions that affect this trade symbol for chart-adjusted display. Each item includes id, symbol, date, ratio, old_conid, and new_conid.
     */
    corporate_action_impact?: Array<{
        [key: string]: unknown;
    }>;
    /**
     * Created At
     *
     * UTC timestamp of when this record was inserted into the database.
     */
    created_at: string;
    /**
     * Updated At
     *
     * UTC timestamp of the most recent update to this record.
     */
    updated_at: string;
};

/**
 * TradeSortField
 *
 * Sortable fields for the trade list.
 */
export type TradeSortField = 'symbol' | 'direction' | 'asset_class' | 'entry_price' | 'exit_price' | 'pnl' | 'quantity' | 'opened_at' | 'closed_at';

/**
 * TradeUpdate
 *
 * Request schema for partially updating an existing trade.
 *
 * All fields are optional.  Pydantic v2 distinguishes between a field
 * that was **omitted** (not in ``model_fields_set``) and one that was
 * **explicitly set to** ``null`` (present in ``model_fields_set`` with
 * value ``None``).  The repository layer uses
 * ``model_dump(exclude_unset=True)`` so that:
 *
 * - Omitting a field → the DB column is left unchanged.
 * - Sending ``"field": null`` → the DB column is set to ``NULL``.
 *
 * This is particularly important for nullable optional fields such as
 * ``stop_loss`` and ``take_profit``.
 *
 * Attributes:
 * symbol: Updated ticker symbol.
 * direction: Updated direction.
 * asset_class: Updated asset class.
 * stop_loss: Updated stop-loss level; ``null`` clears it.
 * take_profit: Updated take-profit level; ``null`` clears it.
 * journal: Updated journal text.
 */
export type TradeUpdate = {
    /**
     * Symbol
     *
     * Updated ticker symbol. Maximum 30 characters. Omit to leave unchanged.
     */
    symbol?: string | null;
    /**
     * Updated trade direction — 'LONG' or 'SHORT'. Omit to leave unchanged.
     */
    direction?: Direction | null;
    /**
     * Updated asset class of the instrument. Omit to leave unchanged.
     */
    asset_class?: AssetClass | null;
    /**
     * Stop Loss
     *
     * Updated stop-loss price level. Set to null to remove the stop-loss. Omit to leave unchanged. Pydantic v2 tracks whether this field was explicitly set via ``model_fields_set``; the repository uses ``model_dump(exclude_unset=True)`` so that an explicit ``null`` clears the field while omitting it leaves it unchanged.
     */
    stop_loss?: number | string | null;
    /**
     * Take Profit
     *
     * Updated take-profit price level. Set to null to remove the take-profit. Omit to leave unchanged. Pydantic v2 tracks whether this field was explicitly set via ``model_fields_set``; the repository uses ``model_dump(exclude_unset=True)`` so that an explicit ``null`` clears the field while omitting it leaves it unchanged.
     */
    take_profit?: number | string | null;
    /**
     * Journal
     *
     * Updated free-text journal. Set to null to clear existing journal. Omit to leave unchanged.
     */
    journal?: string | null;
    /**
     * User Rating
     *
     * Updated user rating on a 1-5 scale. Set to null to clear existing rating. Omit to leave unchanged.
     */
    user_rating?: number | null;
    /**
     * Tradingview Link
     *
     * Updated TradingView link. Set to null to clear. Omit to leave unchanged.
     */
    tradingview_link?: string | null;
    /**
     * Image Urls
     *
     * Replacement list of image URLs. When supplied, existing image URLs are replaced with this set. Omit to leave image URLs unchanged. Pass an empty list ``[]`` to remove all images.
     */
    image_urls?: Array<string> | null;
    /**
     * Playbook Id
     *
     * Updated playbook UUID. Set to null to clear. Omit to leave unchanged.
     */
    playbook_id?: string | null;
    /**
     * Taxonomy Ids
     *
     * Replacement list of taxonomy UUIDs. When supplied, existing taxonomies are replaced with this set. Omit to leave taxonomies unchanged. Pass an empty list ``[]`` to remove all taxonomies.
     */
    taxonomy_ids?: Array<string> | null;
};

